module Datapath_2_STR #(parameter dp_width = 8, R2_width = 4)(   output [R2_width -1: 0] 	count,   output 						Zero,   input [dp_width -1: 0] 		data,      input 						Load_regs, Add_shift, clock, reset_b);  supply1 						pwr;  supply0 						gnd;  wire [dp_width -1: 0] R1_Dbus, R1;  wire [R2_width -1: 0] R2_Dbus;  wire DR1_0, DR1_1, DR1_2, DR1_3, DR1_4, DR1_5, DR1_6, DR1_7;  wire R1_0, R1_1, R1_2, R1_3, R1_4, R1_5, R1_6, R1_7;  wire R2_0, R2_1, R2_2, R2_3;     wire [R2_width -1: 0] R2 = {R2_3, R2_2, R2_1, R2_0};  assign count = {R2_3, R2_2, R2_1, R2_0};  assign R1 = { R1_7, R1_6, R1_5, R1_4, R1_3, R1_2, R1_1, R1_0};  assign DR1_0 = R1_Dbus[0];  assign DR1_1 = R1_Dbus[1];  assign DR1_2 = R1_Dbus[2];  assign DR1_3 = R1_Dbus[3];  assign DR1_4 = R1_Dbus[4];  assign DR1_5 = R1_Dbus[5];  assign DR1_6 = R1_Dbus[6];  assign DR1_7 = R1_Dbus[7];  nor (Zero, R1_0, R1_1, R1_2, R1_3, R1_4, R1_5, R1_6, R1_7);  not (Load_regs_b, Load_regs);  DFF DF_0 (R1_0, DR1_0, clock, pwr);		// Disable reset  DFF DF_1 (R1_1, DR1_1, clock, pwr);  DFF DF_2 (R1_2, DR1_2, clock, pwr);  DFF DF_3 (R1_3, DR1_3, clock, pwr);  DFF DF_4 (R1_4, DR1_4, clock, pwr);  DFF DF_5 (R1_5, DR1_5, clock, pwr);  DFF DF_6 (R1_6, DR1_6, clock, pwr);  DFF DF_7 (R1_7, DR1_7, clock, pwr);  DFF DR_0 (R2_0, DR2_0, clock, Load_regs_b);	// Load_regs (set) drives R2 to all ones  DFF DR_1 (R2_1, DR2_1, clock, Load_regs_b);  DFF DR_2 (R2_2, DR2_2, clock, Load_regs_b);  DFF DR_3 (R2_3, DR2_3, clock, Load_regs_b);  assign DR2_0 = R2_Dbus[0];  assign DR2_1 = R2_Dbus[1];  assign DR2_2 = R2_Dbus[2];  assign DR2_3 = R2_Dbus[3];  wire [1: 0] 				sel = {Add_shift, Load_regs};  wire [dp_width -1: 0] 	R1_shifted = {1'b0, R1_7, R1_6, R1_5, R1_4, R1_3, R1_2, R1_1};  wire [R2_width -1: 0] 	sum = R2 + {3'b000, R1[0]};  Mux8_4_x_1 M0 (R1_Dbus, R1, data, R1_shifted, R1, sel);  Mux4_2_x_1 M1 (R2_Dbus, R2, sum, Add_shift);endmodulemodule Mux8_4_x_1 #(parameter dp_width = 8) (output reg [dp_width -1: 0] mux_out,   input [dp_width -1: 0] in0, in1, in2, in3, input [1: 0] sel);  always @ (in0, in1, in2, in3, sel)    case (sel)      2'b00:	mux_out = in0;      2'b01:	mux_out = in1;      2'b10:	mux_out = in2;      2'b11:	mux_out = in3;    endcaseendmodulemodule Mux4_2_x_1 #(parameter dp_width = 4) (output [dp_width -1: 0] mux_out,   input [dp_width -1: 0] in0, in1, input  sel);  assign mux_out = sel ? in1: in0;endmodule// Test Plan for Datapath Unit:// Demonstrate action of Load_regs// R1 gets data, R2 gets all ones// Demonstrate action of Incr_R2// Demonstrate action of Add_shift and detect Zero// Test bench for datapath module t_Datapath_Unit #(parameter dp_width = 8, R2_width = 4)( );  wire [R2_width -1: 0] 	count;  wire 					Zero;  reg [dp_width -1: 0] 	data;   reg 					Load_regs, Add_shift, clock, reset_b;  Datapath_2_STR M0 (count,  Zero, data, Load_regs, Add_shift, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    data = 8'haa;    Load_regs = 0;    Add_shift = 0;    #10 Load_regs = 1;    #20 Load_regs = 0;    #50 Add_shift = 1;    #140 Add_shift = 0;  joinendmodule